 cleanupWave(){if(!this.original)return;const old=this.original,g=this.g(),onArenaMap=this.r.get16(g+0x4870)*256+this.r.get16(g+0x4872)===1;this.instances.clear();if(onArenaMap){for(let i=0;i<=20;i++)this.call('Monster_freeMonster',[i]);this.call('Monster_freeBoss');}if(this.r.get16(g+0x4886)!==old.slot){this.original=null;return;}this.call('Map_freeData');this.call('Map_freeTile');this.call('Map_loadData',[old.area,old.map,1]);this.call('Map_loadTile',[0]);this.wr16(g+0x4890,old.x);this.wr16(g+0x4892,old.y);this.original=null;}
 selectedItem(){const r=this.r,g=this.g(),u=r.exports.get('GameUI'),slot=r.get16(g+0x4886);if(slot>=10||!u)return null;let pool=-1;const state=r.get32(u+0x7c),cursor=r.get16(u+0x56);if(state===0x10000002&&cursor<200)pool=r.get16(u+0x2e8+2*cursor);else if(state===0x20000002&&cursor<24){const bag=r.get16(u+0x58);if(bag<4&&cursor<r.get16(g+0x433c+bag*0x92)){const rec=g+0x433e+bag*0x92+6*cursor;if(r.get16(rec)===0&&r.get16(rec+4))pool=r.get16(rec+2);}}else {const p=r.get32(g+0x4584);if(p>=g+0x2ed6&&(p-g-0x2ed6)%20===0)pool=(p-g-0x2ed6)/20;}if(pool<0||pool>=200||!r.read(g+0x2e0c+pool,1)[0])return null;const bytes=r.read(g+0x2ed6+20*pool,20),type=(bytes[0]|bytes[1]<<8)>>>5&7;return {slot,pool,bytes,kind:type<=2?Kind.Weapon:type<=6?Kind.Armor:Kind.Other};}
